-- ============================================
-- Tabla: conversations
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."conversations" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "contact_id" UUID NOT NULL,
    "assigned_user_id" UUID,
    "channel" VARCHAR(20) NOT NULL,
    "status" VARCHAR(20) DEFAULT 'OPEN'::character varying NOT NULL,
    "priority" VARCHAR(10) DEFAULT 'MEDIUM'::character varying NOT NULL,
    "subject" VARCHAR(200),
    "channel_conversation_id" VARCHAR(100),
    "last_message_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "first_response_at" TIMESTAMP,
    "resolved_at" TIMESTAMP,
    "closed_at" TIMESTAMP,
    "response_time_seconds" BIGINT,
    "resolution_time_seconds" BIGINT,
    "message_count" INTEGER DEFAULT 0 NOT NULL,
    "unread_count" INTEGER DEFAULT 0 NOT NULL,
    "satisfaction_rating" INTEGER,
    "satisfaction_feedback" VARCHAR(1000),
    "tags" VARCHAR(500),
    "metadata" TEXT,
    "is_bot_conversation" BOOLEAN DEFAULT false NOT NULL,
    "bot_handoff_at" TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "bot_fallback_count" INTEGER DEFAULT 0 NOT NULL
);


-- ============================================
-- Tabla: flyway_schema_history
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."flyway_schema_history" (
    "installed_rank" INTEGER NOT NULL,
    "version" VARCHAR(50),
    "description" VARCHAR(200) NOT NULL,
    "type" VARCHAR(20) NOT NULL,
    "script" VARCHAR(1000) NOT NULL,
    "checksum" INTEGER,
    "installed_by" VARCHAR(100) NOT NULL,
    "installed_on" TIMESTAMP DEFAULT now() NOT NULL,
    "execution_time" INTEGER NOT NULL,
    "success" BOOLEAN NOT NULL
);


-- ============================================
-- Tabla: knowledge_base
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."knowledge_base" (
    "id" UUID NOT NULL,
    "tenant_id" UUID NOT NULL,
    "title" VARCHAR(500) NOT NULL,
    "content" TEXT NOT NULL,
    "source_type" VARCHAR(20) DEFAULT 'manual'::character varying NOT NULL,
    "source_url" VARCHAR(1000),
    "file_url" VARCHAR(500),
    "tags" VARCHAR(500),
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL
);

FSI Implementos Agrícolas es una empresa peruana especializada en la fabricación de cosechadoras de papa, picadoras agrícolas, desbrozadoras e implementos para el campo. Nacemos como respuesta a la necesidad de todos los agricultores y empresas agroindustriales del país en hacer más fácil la tarea del agricultor y realizarlo en menos tiempo. Más de 30 años de experiencia fabricando cosechadoras, picadoras, maquinaria e implementos agrícolas para el campo peruano a los mejores precios. F.S.I SAC, desarrolla, innova, fabrica cosechadoras, picadoras, desbrozadoras y maquinaria agrícola para tractor en Perú.

Nuestra Misión
