INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('fe5b3209-aa83-496a-b7de-36c32f1ab6d3', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'contactar_asesor', 'Solicitud de contacto con un agente humano', '["agente","asesor","hablar con alguien","persona","operador","atención al cliente","ejecutivo","representante","transferir"]', '["Por supuesto, te conectamos con un asesor en este momento. Por favor, espera un instante.","Claro, un asesor se comunicará contigo a la brevedad. Gracias por tu paciencia.","Entiendo, en un momento te atenderá un agente. Por favor, mantente en línea."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 5, 0, '2026-07-30T03:19:07.611230', '2026-07-30T03:19:07.611230', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('8c8c305b-f6db-4f4e-94b9-52771a0bb293', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'consulta_envio', 'Consultas sobre envíos y entregas', '["envío","delivery","despacho","entrega","cuándo llega","tiempo de entrega","demora","seguimiento de pedido","rastrear"]', '["El tiempo de entrega estimado es de 2 a 5 días hábiles dentro de Lima y de 5 a 7 días hábiles para provincias. ¿Te gustaría rastrear tu pedido?","Realizamos envíos a todo el Perú. El costo y tiempo de entrega varían según tu ubicación. ¿Podrías indicarme tu distrito o ciudad para darte mayor precisión?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 6, 0, '2026-07-30T03:19:07.611230', '2026-07-30T03:19:07.611230', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('e6d1cc5c-af6e-410a-9cdc-638ca9e314ee', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'forma_pago', 'Consultas sobre métodos de pago', '["pago","pagar","tarjeta","transferencia","yape","plin","efectivo","depósito","métodos de pago"]', '["Aceptamos pagos con tarjeta de crédito/débito, transferencia bancaria, Yape y Plin. ¿Cuál es tu método de pago preferido?","Puedes pagar con tarjeta (Visa, Mastercard), transferencia bancaria, Yape o Plin. ¿Cuál te resulta más conveniente?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 7, 0, '2026-07-30T03:19:07.614104', '2026-07-30T03:19:07.614104', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('3f77ce32-52a2-4ef2-9d4e-f1ac9ca16a73', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'queja_reclamo', 'Atención de quejas o reclamos', '["queja","reclamo","problema","insatisfecho","error","mal servicio","devolución","me quejo"]', '["Lamento mucho el inconveniente. Permíteme revisar tu caso para darte una solución rápida. ¿Podrías contarme un poco más sobre lo sucedido?","Agradecemos tu feedback, ya que nos ayuda a mejorar. Un asesor especializado revisará tu caso y te contactará a la brevedad.","Lamento el problema que has experimentado. Déjame tus datos y un supervisor se comunicará contigo en los próximos minutos para resolverlo."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 8, 0, '2026-07-30T03:19:07.614104', '2026-07-30T03:19:07.614104', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('c3b2f5fa-134f-4c9a-a10a-f8dc3821f7a8', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'informacion_empresa', 'Solicitud de información general de la empresa', '["quiénes son","empresa","acerca de","información","quién es","sobre ustedes","qué hacen"]', '["Somos una empresa comprometida con brindar el mejor servicio a nuestros clientes. ¿Hay algo específico que te gustaría saber sobre nosotros? Con gusto te informamos.","Con gusto te brindamos información sobre nuestra empresa. ¿Hay algo en particular que te gustaría conocer?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 9, 0, '2026-07-30T03:19:07.614104', '2026-07-30T03:19:07.614104', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('b11a5390-4683-4c26-b2a5-874bd6374163', 'af0cd8b3-b19b-4c55-8b6a-e23623bbc90b', 'despedida', 'Despedidas cordiales', '["gracias","adiós","chau","hasta luego","nos vemos","que tengas buen día","muchas gracias","gracias por tu atención"]', '["Gracias a ti por contactarnos. ¡Que tengas un excelente día! Si necesitas algo más, aquí estamos.","Ha sido un placer atenderte. No dudes en escribirnos si requieres algo más. ¡Hasta pronto!","¡Gracias por comunicarte! Quedo atento por si surge cualquier otra consulta. Que tengas un maravilloso día."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 10, 0, '2026-07-30T03:19:07.614104', '2026-07-30T03:19:07.614104', NULL, NULL, 0, NULL, NULL, FALSE);
