INSERT INTO "public"."conversation_messages" ("id", "tenant_id", "conversation_id", "user_id", "direction", "type", "status", "content", "channel_message_id", "reply_to_message_id", "sender_name", "sender_phone", "sender_email", "is_from_bot", "bot_intent", "bot_confidence", "sent_at", "delivered_at", "read_at", "failed_at", "failure_reason", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "sender_type") VALUES ('30b915eb-ac7b-4a47-b9ec-e159e7ffe8b2', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', 'fb81cec0-c292-4d6d-9bfe-f547c54885a7', NULL, 'OUTBOUND', 'TEXT', 'FAILED', 'Mira... me parece que has compartido una noticia interesante sobre LEGO y su colaboración con Shrek. Sin embargo, no veo una consulta específica sobre nuestros productos agrícolas. ¿Hay algo en particular que te gustaría saber o en lo que pueda ayudarte? Estoy aquí para escucharte y ofrecerte asesoramiento sobre nuestros equipos y máquinas agrícolas. ¿Tienes alguna pregunta o necesitas recomendaciones sobre cómo mejorar tu proceso de cultivo o cosecha? Estoy a tu disposición.', NULL, NULL, NULL, NULL, NULL, TRUE, 'unknown', NULL, '2026-07-31T16:23:30.524455', NULL, NULL, NULL, NULL, NULL, '2026-07-31T16:23:30.524455', '2026-07-31T16:23:30.524455', NULL, NULL, 0, 'BOT');
