INSERT INTO "public"."conversation_messages" ("id", "tenant_id", "conversation_id", "user_id", "direction", "type", "status", "content", "channel_message_id", "reply_to_message_id", "sender_name", "sender_phone", "sender_email", "is_from_bot", "bot_intent", "bot_confidence", "sent_at", "delivered_at", "read_at", "failed_at", "failure_reason", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "sender_type") VALUES ('66293d69-0b57-41b9-9a3f-24724dbf1d5e', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', 'c4cb496b-536a-4a51-a7a8-71d01ada219d', NULL, 'OUTBOUND', 'TEXT', 'FAILED', 'Gracias por escribirnos. Me disculpas, pero no logré entender completamente tu consulta. Para poder ayudarte de la mejor manera, ¿podrías indicarme con mayor detalle qué es exactamente lo que deseas? Por ejemplo: el nombre del producto, el modelo o la información que necesitas. Un agente humano está al tanto de tu mensaje y te atenderá muy pronto. ¡Gracias por tu paciencia y confianza!', NULL, NULL, NULL, NULL, NULL, TRUE, 'unknown', NULL, '2026-07-31T16:23:32.157227', NULL, NULL, NULL, NULL, NULL, '2026-07-31T16:23:32.157760', '2026-07-31T16:23:32.157760', NULL, NULL, 0, 'BOT');
