INSERT INTO "public"."conversation_messages" ("id", "tenant_id", "conversation_id", "user_id", "direction", "type", "status", "content", "channel_message_id", "reply_to_message_id", "sender_name", "sender_phone", "sender_email", "is_from_bot", "bot_intent", "bot_confidence", "sent_at", "delivered_at", "read_at", "failed_at", "failure_reason", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "sender_type") VALUES ('93d6b480-862a-4add-bc66-dcd952f9bac6', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', '7babdd64-a6be-454f-8fca-0bb9969fa041', NULL, 'OUTBOUND', 'TEXT', 'SENT', '😊 Fue un placer conocerte también. Aunque no hemos tenido la oportunidad de hablar sobre nuestros productos todavía, espero que pronto podamos hacerlo y encontrar la solución perfecta para tus necesidades. ¡Que tengas un excelente día y nos vemos pronto! 🙏', '3EB0804EA075CBF2641D30', NULL, NULL, NULL, NULL, TRUE, 'unknown', NULL, '2026-07-31T05:47:31.642076', NULL, NULL, NULL, NULL, NULL, '2026-07-31T05:47:31.642705', '2026-07-31T05:47:31.642705', NULL, NULL, 0, 'BOT');
INSERT INTO "public"."conversation_messages" ("id", "tenant_id", "conversation_id", "user_id", "direction", "type", "status", "content", "channel_message_id", "reply_to_message_id", "sender_name", "sender_phone", "sender_email", "is_from_bot", "bot_intent", "bot_confidence", "sent_at", "delivered_at", "read_at", "failed_at", "failure_reason", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "sender_type") VALUES ('4b4191ae-76c6-47b8-8ac8-51ccfc992971', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', '7babdd64-a6be-454f-8fca-0bb9969fa041', NULL, 'OUTBOUND', 'TEXT', 'SENT', '¡De nada! Fue un placer charlar contigo, aunque no haya sido sobre ninguno de nuestros productos en particular esta vez. 😊 Si en algún momento necesitas asesoramiento o información sobre nuestras máquinas agrícolas, no dudes en volver a contactarme. Estoy aquí para ayudarte. ¡Que tengas un excelente día y hasta pronto! 🙏', '3EB0E1BC1C32A584D1F1B5', NULL, NULL, NULL, NULL, TRUE, 'unknown', NULL, '2026-07-31T05:47:42.376775', NULL, NULL, NULL, NULL, NULL, '2026-07-31T05:47:42.376775', '2026-07-31T05:47:42.376775', NULL, NULL, 0, 'BOT');
