INSERT INTO "public"."products" ("id", "tenant_id", "sku", "name", "description", "short_description", "price", "compare_at_price", "cost_price", "category_id", "stock_quantity", "low_stock_threshold", "status", "image_url", "images", "weight", "width", "height", "length", "is_featured", "tags", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('68071168-f8b7-43af-a44c-7313fd38a771', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', NULL, 'Desemplastificador Agrícola / Recolector de plástico y cinta', 'Equipo agrícola diseñado para la recolección eficiente de plástico y cinta de riego en los campos de cultivo. Incorpora un sistema hidráulico que facilita la operación, optimiza el tiempo de trabajo y contribuye al mantenimiento limpio y ordenado del terreno.
INSERT INTO "public"."products" ("id", "tenant_id", "sku", "name", "description", "short_description", "price", "compare_at_price", "cost_price", "category_id", "stock_quantity", "low_stock_threshold", "status", "image_url", "images", "weight", "width", "height", "length", "is_featured", "tags", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('1b064d36-e8e1-4f7e-a17a-2b1e70e388b4', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', NULL, 'Subsolador de 3 Brazos', 'Subsolador de 3 Brazos. Equipo agrícola diseñado para romper y airear el suelo a mayor profundidad, mejorando la infiltración de agua y el desarrollo radicular. Sus tres brazos robustos permiten un trabajo eficiente en terrenos compactados, optimizando la preparación del terreno para siembras de alto rendimiento. Construido con materiales resistentes para mayor durabilidad y adaptado a distintas condiciones de cultivo.
INSERT INTO "public"."products" ("id", "tenant_id", "sku", "name", "description", "short_description", "price", "compare_at_price", "cost_price", "category_id", "stock_quantity", "low_stock_threshold", "status", "image_url", "images", "weight", "width", "height", "length", "is_featured", "tags", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('9bc72407-6bea-4c08-a980-905134286af9', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', NULL, 'Cosechadora de Papa de Cola Larga CPFSI - 4', 'Máquina agrícola diseñada para extraer papas del suelo de forma eficiente con estructura extendida en la parte trasera que permite depositar las papas directamente en un remolque o carro mientras la máquina avanza, lo que mejora el rendimiento y reduce el daño a los tubérculos. Es ideal para trabajos en campos amplios y para operaciones que buscan optimizar el tiempo de cosecha.
INSERT INTO "public"."products" ("id", "tenant_id", "sku", "name", "description", "short_description", "price", "compare_at_price", "cost_price", "category_id", "stock_quantity", "low_stock_threshold", "status", "image_url", "images", "weight", "width", "height", "length", "is_featured", "tags", "metadata", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('bd19df3d-0f80-4309-ba8a-52e765479b79', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', NULL, 'Cosechadora de Papa con Descarga Lateral', 'La cosechadora de papa con descarga lateral de FSI Implementos Agrícolas está diseñada para maximizar la eficiencia en la recolección. Su sistema de descarga lateral permite un vaciado continuo y rápido, optimizando tiempos de trabajo. Construida con materiales resistentes y de alta durabilidad, garantiza un desempeño óptimo en terrenos exigentes. Ideal para pequeños y medianos agricultores que buscan rendimiento, ahorro y facilidad de operación. Respaldada con garantía, asesoría técnica y repuestos inmediatos en todo el Perú.
